                when (kind) {
                    "BlockChanged" -> BlockChanged(block = field(data, "block", String.serializer()), doc = field(data, "doc", String.serializer()))
                    "BlockDeleted" -> BlockDeleted(block = field(data, "block", String.serializer()), doc = field(data, "doc", String.serializer()))
                    "BlockInserted" -> BlockInserted(block = field(data, "block", String.serializer()), doc = field(data, "doc", String.serializer()))
                    "BlockMoved" -> BlockMoved(block = field(data, "block", String.serializer()), doc = field(data, "doc", String.serializer()))
                    "CommentAdded" -> CommentAdded(id = field(data, "id", String.serializer()))
                    "CommentDeleted" -> CommentDeleted(id = field(data, "id", String.serializer()))
                    "CommentEdited" -> CommentEdited(id = field(data, "id", String.serializer()))
                    "DocArchived" -> DocArchived(id = field(data, "id", String.serializer()))
                    "DocCreated" -> DocCreated(id = field(data, "id", String.serializer()))
                    "DocDeleted" -> DocDeleted(id = field(data, "id", String.serializer()))
                    "DocEdited" -> DocEdited(id = field(data, "id", String.serializer()))
                    "DocTagsChanged" -> DocTagsChanged(id = field(data, "id", String.serializer()))
                    "DocUnarchived" -> DocUnarchived(id = field(data, "id", String.serializer()))
                    "ManagerAdded" -> ManagerAdded(member = field(data, "member", String.serializer()))
                    "ManagerRemoved" -> ManagerRemoved(member = field(data, "member", String.serializer()))
                    "MarkApplied" -> MarkApplied(block = field(data, "block", String.serializer()), doc = field(data, "doc", String.serializer()), markId = field(data, "markId", String.serializer()))
                    "TagChanged" -> TagChanged(key = field(data, "key", String.serializer()))
                    "TextChanged" -> TextChanged(block = field(data, "block", String.serializer()), doc = field(data, "doc", String.serializer()))
                    "TitleChanged" -> TitleChanged(doc = field(data, "doc", String.serializer()))
                    "ViewChanged" -> ViewChanged(id = field(data, "id", String.serializer()))
                    else -> Unknown(kind, data)
                }
        }
    }

